import sys
import json
import pandas as pd
import numpy as np

def to_float(x):
    return float(x)

def round_val(metric, period, value):
    if metric == "revenue" and period in ("TW", "LW", "LY"):
        return round(to_float(value), 2)
    if period in ("WoW", "YoY") or metric == "share":
        return round(to_float(value), 1)
    if metric in ("units", "orders", "rank"):
        return round(to_float(value), 0)
    return round(to_float(value), 2)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    def add(entity, metric, period, value, formula):
        if value is None:
            return
        if isinstance(value, float) and np.isnan(value):
            return
        facts.append({
            "entity": entity,
            "metric": metric,
            "period": period,
            "value": round_val(metric, period, value),
            "formula": formula
        })

    # --- TOTALS ---
    rev_tw_total = df["Revenue_TW"].sum(skipna=True)
    rev_lw_total = df["Revenue_LW"].sum(skipna=True)
    rev_ly_series = df["Revenue_LY"]
    rev_ly_total = rev_ly_series.sum(skipna=True) if rev_ly_series.notna().any() else np.nan

    units_tw_total = df["Units_TW"].sum(skipna=True)
    units_lw_total = df["Units_LW"].sum(skipna=True)
    orders_tw_total = df["Orders_TW"].sum(skipna=True)
    orders_lw_total = df["Orders_LW"].sum(skipna=True)

    add("TOTAL", "revenue", "TW", rev_tw_total, "sum(Revenue_TW)")
    add("TOTAL", "revenue", "LW", rev_lw_total, "sum(Revenue_LW)")
    if not np.isnan(rev_ly_total):
        add("TOTAL", "revenue", "LY", rev_ly_total, "sum(Revenue_LY)")

    if rev_lw_total and not np.isnan(rev_lw_total) and rev_lw_total != 0:
        wow_total = (rev_tw_total - rev_lw_total) / rev_lw_total * 100
        add("TOTAL", "revenue", "WoW", wow_total,
            "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100")

    if not np.isnan(rev_ly_total) and rev_ly_total != 0:
        yoy_total = (rev_tw_total - rev_ly_total) / rev_ly_total * 100
        add("TOTAL", "revenue", "YoY", yoy_total,
            "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100")

    add("TOTAL", "units", "TW", units_tw_total, "sum(Units_TW)")
    add("TOTAL", "units", "LW", units_lw_total, "sum(Units_LW)")
    add("TOTAL", "orders", "TW", orders_tw_total, "sum(Orders_TW)")
    add("TOTAL", "orders", "LW", orders_lw_total, "sum(Orders_LW)")

    # --- Biggest WoW mover / decliner ---
    wow_valid = df.dropna(subset=["WoW_Pct"])
    if not wow_valid.empty:
        top_up = wow_valid.loc[wow_valid["WoW_Pct"].idxmax()]
        top_down = wow_valid.loc[wow_valid["WoW_Pct"].idxmin()]
        add(top_up["Entity"], "revenue", "WoW", top_up["WoW_Pct"],
            "(Revenue_TW - Revenue_LW) / Revenue_LW * 100 (largest increase)")
        if top_down["Entity"] != top_up["Entity"]:
            add(top_down["Entity"], "revenue", "WoW", top_down["WoW_Pct"],
                "(Revenue_TW - Revenue_LW) / Revenue_LW * 100 (largest decrease)")

    # --- Biggest YoY mover (if data available) ---
    yoy_valid = df.dropna(subset=["YoY_Pct"])
    if not yoy_valid.empty:
        top_yoy = yoy_valid.loc[yoy_valid["YoY_Pct"].idxmax()]
        add(top_yoy["Entity"], "revenue", "YoY", top_yoy["YoY_Pct"],
            "(Revenue_TW - Revenue_LY) / Revenue_LY * 100 (largest YoY change)")

    # --- Per-entity facts, ordered by Rank ---
    df_sorted = df.sort_values("Rank", na_position="last")

    for _, row in df_sorted.iterrows():
        if len(facts) >= 25:
            break
        entity = row["Entity"]

        if len(facts) < 25 and not pd.isna(row["Revenue_TW"]):
            add(entity, "revenue", "TW", row["Revenue_TW"], "Revenue_TW")
        if len(facts) < 25 and not pd.isna(row["Share_Pct"]):
            add(entity, "share", "TW", row["Share_Pct"], "Revenue_TW / sum(Revenue_TW) * 100")
        if len(facts) < 25 and not pd.isna(row["Rank"]):
            add(entity, "rank", "TW", row["Rank"], "rank of Revenue_TW descending")
        if len(facts) < 25 and not pd.isna(row["WoW_Pct"]):
            add(entity, "revenue", "WoW", row["WoW_Pct"],
                "(Revenue_TW - Revenue_LW) / Revenue_LW * 100")
        if len(facts) < 25 and not pd.isna(row["YoY_Pct"]):
            add(entity, "revenue", "YoY", row["YoY_Pct"],
                "(Revenue_TW - Revenue_LY) / Revenue_LY * 100")

    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
